package localchat;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.*;
import javax.swing.event.*;

/** Deterministic repaint regressions and exact output provenance; no provider inference. */
public final class RuntimeStabilityTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void write(Path p,String value)throws Exception{Files.createDirectories(p.getParent());Files.writeString(p,value);}
 static DocumentListener changes(AtomicInteger n){return new DocumentListener(){public void insertUpdate(DocumentEvent e){n.incrementAndGet();}public void removeUpdate(DocumentEvent e){n.incrementAndGet();}public void changedUpdate(DocumentEvent e){n.incrementAndGet();}};}
 static List<Hotfolder.Change> changes(Hotfolder watcher,Path root,long t)throws Exception{watcher.scan(root,t);return watcher.scan(root,t+40);}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory("runtime-stability-"),project=Files.createDirectories(home.resolve("sources/123456")),registry=home.resolve("hotfolder-generated.json");
  write(project.resolve("old.eml"),"old email");Hotfolder watcher=new Hotfolder(home.resolve("hotfolder.json"),30);check(watcher.scan(home.resolve("sources"),0).isEmpty(),"initial baseline");
  Path own=project.resolve("Importlijst/test_write.xlsx");
  try(var scope=GeneratedFiles.command(registry,project,"python -c save('Importlijst/test_write.xlsx')")){
   write(own,"generated by shell");check(changes(watcher,home.resolve("sources"),100).isEmpty(),"explicit output ignored while command runs");
   write(project.resolve("new.eml"),"new user email");var fresh=changes(watcher,home.resolve("sources"),150);check(fresh.size()==1&&fresh.get(0).files().equals(List.of("new.eml")),"concurrent new email remains visible");watcher.acknowledge(fresh.get(0));
  }
  check(changes(watcher,home.resolve("sources"),220).isEmpty(),"completed shell output ignored after scope");
  write(own,"user replaces with a new spreadsheet revision");var changed=changes(watcher,home.resolve("sources"),280);check(changed.size()==1&&changed.get(0).files().contains("Importlijst\\test_write.xlsx"),"later user revision of generated file is detected");watcher.acknowledge(changed.get(0));
  Path script=project.resolve("build.py");write(script,"wb.save('generated.xlsx')");GeneratedFiles.mark(registry,List.of(script));
  try(var scope=GeneratedFiles.command(registry,project,"python build.py")){write(project.resolve("generated.xlsx"),"generated by owned script");write(project.resolve("user.pdf"),"unrelated user source");}
  var sources=changes(watcher,home.resolve("sources"),350);check(sources.size()==1&&sources.get(0).files().equals(List.of("user.pdf")),"owned script output excluded without swallowing an unrelated user PDF");watcher.acknowledge(sources.get(0));
  Hotfolder restored=new Hotfolder(home.resolve("hotfolder.json"),30);check(changes(restored,home.resolve("sources"),420).isEmpty(),"provenance survives restart");
  Path toolHome=Files.createDirectories(home.resolve("tool-app")),toolProject=Files.createDirectories(toolHome.resolve("123456"));write(toolProject.resolve("in.eml"),"source");Hotfolder toolWatcher=new Hotfolder(toolHome.resolve("hotfolder.json"),30);toolWatcher.scan(toolProject,0);
  Tools tools=new Tools(new Tools.Context(toolProject,toolHome.resolve("skills"),toolHome.resolve("rules.md"),toolHome.resolve("settings.properties"),Map.of(),null,new Mcp(),PathMap.none(),true,EnumSet.noneOf(Tools.Access.class),(a,b)->Tools.Decision.NO),List.of());
  var result=tools.execute(new ChatClient.ToolCall("write","write_file",Json.obj("path","produced.csv","content","fixture")));check(!result.isError,"actual write tool succeeds");check(changes(toolWatcher,toolProject,100).isEmpty(),"actual write tool registers exact output");
  result=tools.execute(new ChatClient.ToolCall("shell","run_command",Json.obj("command","echo fixture>test_write.xlsx","cwd",toolProject.toString())));check(!result.isError,"actual shell executes");check(changes(toolWatcher,toolProject,200).isEmpty(),"actual shell registers explicit output");
  var first=new Hotfolder.Change("123456",project,false,List.of("first.eml"),"one");var second=new Hotfolder.Change("123456",project,false,List.of("second.eml"),"two");String custom="My unsent question\n\n";String merged=HotfolderChats.append(custom+Hotfolder.prompt(first),Hotfolder.prompt(second));
  check(merged.startsWith(custom)&&merged.contains("first.eml")&&merged.contains("second.eml"),"merge preserves user draft and both sources");check(merged.split("Foloseste read_skill",-1).length==2,"one procedure for multiple source events");
  write(project.resolve("read.xlsx"),"before");try(var scope=GeneratedFiles.command(registry,project,"python -c load_workbook('read.xlsx'); save('output.xlsx')")){write(project.resolve("read.xlsx"),"user changed a read source");write(project.resolve("output.xlsx"),"produced");}
  var readChange=changes(watcher,home.resolve("sources"),500);check(readChange.size()==1&&readChange.get(0).files().contains("read.xlsx")&&!readChange.get(0).files().contains("output.xlsx"),"merely mentioning read source never suppresses user changes");
  var msg=new OutlookMsg.Message("fixture","from","to","","","body",List.of(new OutlookMsg.Attachment("new-attachment.pdf","application/pdf",3,false,new byte[]{1,2,3},null)));
  Path extraction=Files.createDirectories(toolProject.resolve("Attachments"));List<String> report=new ArrayList<>();OutlookMsg.extract(msg,extraction,false,report,p->{try{GeneratedFiles.mark(toolHome.resolve("hotfolder-generated.json"),List.of(p));}catch(Exception e){throw new RuntimeException(e);}});check(changes(toolWatcher,toolProject,300).isEmpty(),"extracted attachment output registered at exact saved path");
  String partialCall=Json.write(Json.obj("choices",List.of(Json.obj("finish_reason","length","message",Json.obj("content","unfinished","tool_calls",List.of(Json.obj("id","truncated-write","type","function","function",Json.obj("name","write_file","arguments",Json.write(Json.obj("path","must-not-exist.txt","content","unsafe partial"))))))))));
  try(var server=new FeatureTest.Server(FeatureTest.json(partialCall))){Agent agent=new Agent(tools);boolean failed=false;try{agent.run(Provider.CUSTOM,server.url(),"","fixture","label","",List.of(ChatClient.Message.user("fixture")),false,new Agent.Ui(){public void text(String s){}public void step(){}public void toolStarted(ChatClient.ToolCall c){throw new AssertionError("Truncated call executed");}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){throw new AssertionError("Truncated call executed");}});}catch(java.io.IOException expected){failed=true;}check(failed&&!Files.exists(toolProject.resolve("must-not-exist.txt")),"truncated reply never executes its tool calls");check(agent.collect("","label").stream().anyMatch(m->m.role.equals("tool")&&m.isError),"truncated tool placeholders retain a valid archive");}
  FeatureTest.edt(()->{
   for(String language:I18n.CODES){I18n.setLanguage(language);ContextUsagePopup popup=new ContextUsagePopup();WorkspacePanel workspace=new WorkspacePanel(()->{},x->{},()->{},()->{});
    for(boolean dark:new boolean[]{false,true}){
     popup.theme(dark);popup.update(100,200,300,10000,"usage fixture");workspace.meter(100,200,300,10000,"usage fixture");AtomicInteger events=new AtomicInteger();popup.explanation.getDocument().addDocumentListener(changes(events));popup.usage.getDocument().addDocumentListener(changes(events));workspace.details.getDocument().addDocumentListener(changes(events));
     for(int i=0;i<1000;i++){popup.update(100,200,300,10000,"usage fixture");workspace.meter(100,200,300,10000,"usage fixture");}
     check(events.get()==0,"unchanged dashboard does not rebuild text documents "+language+dark);popup.update(100,200,301,10000,"new usage");check(events.get()>0&&popup.values[2].getText().contains("301"),"actual update still visible "+language+dark);
    }
    AgentPanel agents=new AgentPanel(()->{},()->{});agents.queued("a","A","task","model");agents.queued("b","B","task","model");agents.busy(true);agents.progress("a","waiting_api");agents.progress("b","compacting");check(agents.runningCount()==2&&agents.summaryState().equals("running"),"waiting and compacting stay active "+language);
   }
  });
  System.out.println("PASS: "+checks+" runtime stability checks");System.exit(0);
 }
}
